cells.counterexample:
public choice Tag
  A(n: int),
  B;
  public method Equals(other: Tag): bool => true;   // replaces the generated Equals (§35.2)
  public method GetHashCode(): int => 0;            // methods neither qualify nor disqualify (§35.7)
end Tag;                                            // so Tag stays auto-hashable

static class Demo
  public static method Same<T>(a: T, b: T): bool where T: hashable => a = b;  // first kind (§9.2)
  public static method Run()
    var x := Tag.A(1);
    var y := Tag.A(2);
    Console.WriteLine($"{x = y}");             // (1) §8.4: no declared `=`, so Equals: True
                                               // (2) §35.7: the generated structural `=`: False
    Console.WriteLine($"{Same<Tag>(x, y)}");   // through T: Tag's own-typed Equals, its slot: True
  end Run;                                     // under (2): one `=`, two definitions at S = Tag
end Demo;
